-- S1 · parte 2.02: proyectos no-se-esta-tan-mal-lovva, ep-oscuridad-adrian-munoz, kiboko
create function pg_temp.med(u text) returns uuid language sql as $$ select id from public.medios where url_origen = u order by creado_en limit 1 $$;
create function pg_temp.gal(urls text[]) returns jsonb language sql as $$ select coalesce(jsonb_agg(jsonb_build_object('medio', pg_temp.med(u), 'pie', '') order by o), '[]'::jsonb) from unnest(urls) with ordinality t(u, o) $$;

insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('no-se-esta-tan-mal-lovva', 'no-se-esta-tan-mal-lovva', 'No se está tan mal, Lovva', (select id from public.tipos_proyecto where slug = 'videoclip'), null, 'Ángela Manzano',
  'Proyecto propio', 'Fotografía y montaje', 'Sony FX3 · Tamron', $t$[]$t$::jsonb,
  $t$Una canción sobre aceptarse a uno mismo, y una imagen pensada como refugio.$t$, $t$Ángela Manzano pedía una burbuja visual donde Lovva pudiera mostrarse vulnerable sin perder fuerza. Para rodarla construimos siete sets.$t$, $t$- **Luz puntual, no plana.** Contraluces, destellos suaves y puntos de luz que envuelven al artista.
- **Cristal y agua.** Reflejos y refracciones que dan textura a cada plano.
- **Un esquema por set.** Cada uno de los siete sets tiene su propia luz.$t$, $t$Que siete espacios distintos se sintieran como un mismo lugar. En montaje los enlacé sin romper la atmósfera ni el ritmo.$t$, '', $t$Una canción vulnerable necesitaba una luz *que la protegiera*.$t$,
  '8E1R23u8jjc', 44, $t$[]$t$::jsonb, false, pg_temp.med('https://i.ibb.co/nN1R7bkV/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-12-047.jpg'), pg_temp.gal(array['https://i.ibb.co/6RLX7RwQ/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-05-391.jpg','https://i.ibb.co/hJ70TfQW/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-02-20-863.jpg','https://i.ibb.co/tPwcqPyC/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-44-400.jpg','https://i.ibb.co/Wp7ZCfxz/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-01-25-345.jpg','https://i.ibb.co/TDs4pBhq/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-02-41-047.jpg','https://i.ibb.co/nN1R7bkV/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-12-047.jpg']), 4, 4, 'publicado', now())
