values ('ep-oscuridad-adrian-munoz', 'ep-oscuridad-adrian-munoz', 'EP Oscuridad, Adrián Muñoz', (select id from public.tipos_proyecto where slug = 'videoclip'), null, 'JUNO Media',
  'JUNO Media', 'Dirección de fotografía', 'Sony FX3 · Tamron y Sony', $t$[{"nombre":"1,39 M visualizaciones","tipo":"cifra","festival":"YouTube y plataformas"}]$t$::jsonb,
  $t$Un EP sobre una pareja que se rompe, contado en siete visualizers y un tráiler.$t$, $t$Adrián Muñoz recorre el enfado, la soledad, la ruptura, las cicatrices y la resignación. Mi trabajo fue pensar la imagen de la serie entera, no de cada vídeo por separado.$t$, $t$- **Pantalla partida.** El artista a un lado y la pareja al otro, encuadrados e iluminados para leerse juntos.
- **De color a blanco y negro.** Cada tema pierde saturación hasta el séptimo.
- **Una luz por emoción.** Un esquema distinto para cada bucle, siempre con contraste cuidado.$t$, $t$Siete piezas que se ven sueltas en redes. El paso del color al blanco y negro le da a cada una su identidad y, a la vez, las ordena.$t$, $t$- 1.392.400 visualizaciones entre YouTube, Instagram y Spotify.$t$, $t$Siete canciones y un color que se apaga hasta el *blanco y negro*.$t$,
  'At7qqcIhdHw', 30, $t$[]$t$::jsonb, false, pg_temp.med('https://i.imgur.com/MgsvdAf.png'), pg_temp.gal(array['https://i.imgur.com/MgsvdAf.png','https://i.ibb.co/Q7ZBv1XG/Captura-de-pantalla-2026-05-12-190438.png','https://i.ibb.co/RdNPNMz/Captura-de-pantalla-2026-05-12-190601.png','https://i.ibb.co/fd9B05gY/Captura-de-pantalla-2026-05-12-190728.png','https://i.ibb.co/KccQH5Pd/Captura-de-pantalla-2026-05-12-190900.png','https://i.ibb.co/rG5phXmZ/Captura-de-pantalla-2026-05-12-191105.png','https://i.ibb.co/xKVznYVn/Captura-de-pantalla-2026-05-12-191155.png']), 5, 5, 'publicado', now())
