values ('kiboko', 'kiboko', 'Kiboko', (select id from public.tipos_proyecto where slug = 'documental'), 2026, 'Noelia Fluxá y Julie-Estel Soard',
  'JUNO Media y Arca Films', 'Montaje', 'Solo montaje (rodado en ARRI)', $t$[{"anio":2026,"nombre":"Nominación a mejor montaje","tipo":"nominacion"}]$t$::jsonb,
  $t$El bar Kiboko fue un refugio de libertad y música en La Vila Joiosa de los 80. Esta docuficción lo recupera.$t$, $t$Lo cuenta Ana, una cronista ficticia que hoy investiga el local. Mi trabajo fue unir tres materiales en un solo relato: entrevistas reales, escenas de ficción y su voz en off.$t$, $t$- **Ordenar primero.** Sincronizar, cribar y estructurar horas de entrevistas antes de buscar el ritmo.
- **Testimonio y ficción en diálogo.** Las entrevistas responden a lo que Ana investiga.
- **Dos ritmos.** Vibrante en el bar de 1986, apoyado en la música; pausado en las entrevistas.$t$, $t$El volumen: horas de material en tres formatos distintos, y una historia que no podía perder el foco ni la emoción.$t$, $t$- Estreno con aforo completo en el Teatre Auditori de La Vila Joiosa, el 6 de junio de 2026.
- Selección en festivales y nominación a mejor montaje.$t$, $t$Memoria real y ficción, montadas para que no se vean *las costuras*.$t$,
  'O-TDpUpxIGw', 30, $t$[]$t$::jsonb, false, pg_temp.med('https://i.ibb.co/vx4gxGQh/Captura-de-pantalla-2026-05-12-201300.png'), pg_temp.gal(array['https://i.ibb.co/vx4gxGQh/Captura-de-pantalla-2026-05-12-201300.png','https://i.ibb.co/pB88YNSL/INICIOKIBOKO-V6-mp4-snapshot-00-12-000.jpg','https://i.ibb.co/fGHZtRV6/INICIOKIBOKO-V6-mp4-snapshot-01-50-777.jpg','https://i.ibb.co/yn3Y5k4T/INICIOKIBOKO-V6-mp4-snapshot-03-00-000.jpg']), 6, 6, 'publicado', now())
